const {chromium}=require('playwright');const fs=require('fs');const crypto=require('crypto');
(async()=>{const rows=JSON.parse(fs.readFileSync('seo/autoridade-20261030-manifest.json','utf8'));const b=await chromium.launch({headless:true});const results=[];
try{for(const r of rows){for(const [device,width,height] of [['mobile',390,844],['desktop',1440,900]]){const p=await b.newPage({viewport:{width,height}});const response=await p.goto(r.url,{waitUntil:'domcontentloaded',timeout:45000});const got=await p.evaluate(()=>({title:document.title,h1:document.querySelector('h1')?.textContent,canonical:document.querySelector('link[rel=canonical]')?.href,robots:document.querySelector('meta[name=robots]')?.content,overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth,jsonld:[...document.querySelectorAll('script[type="application/ld+json"]')].map(x=>JSON.parse(x.textContent)),marker:document.documentElement.outerHTML.includes('ARQ-AUTORIDADE-20261030')}));
if(response.status()!==200||got.canonical!==r.url||!got.h1||got.overflow||!got.marker||got.robots.includes('noindex'))throw new Error('PUBLIC_QA_FAILED '+r.url+' '+JSON.stringify(got));
console.log('PUBLIC_PAGE_OK',device,r.url);results.push({url:r.url,device,status:response.status(),canonical:got.canonical,overflow:got.overflow});await p.screenshot({path:'publish-report/autoridade-20261030/'+rows.indexOf(r)+'-'+device+'.png',fullPage:true});await p.close();}}
const page=await b.newPage();const api=page.request;let sm=await api.get('https://www.arquindex.com.br/sitemap-autoridade-20261030.xml');const text=await sm.text();if(sm.status()!=200||!rows.every(r=>text.includes(r.url)))throw new Error('SITEMAP_PUBLIC_FAILED');
const k=JSON.parse(fs.readFileSync('publish-report/autoridade-20261030/indexnow-public-key.json'));const kr=await api.get(k.url);if(kr.status()!=200||(await kr.text()).trim()!==k.key)throw new Error('INDEXNOW_KEY_PUBLIC_FAILED');
let robots=await api.get('https://www.arquindex.com.br/robots.txt');if(robots.status()!=200)throw new Error('ROBOTS_UNREACHABLE');fs.writeFileSync('publish-report/autoridade-20261030/robots.txt',await robots.text());
const d=JSON.parse(fs.readFileSync('publish-report/autoridade-20261030/publication.json'));d.http_verified=true;d.sitemap_verified=true;d.key_file_verified=true;d.public_checks=results;fs.writeFileSync('publish-report/autoridade-20261030/publication.json',JSON.stringify(d,null,2));console.log('PUBLIC_SITEMAP_AND_KEY_OK');await page.close();
}finally{await b.close();}})().catch(e=>{console.error(e);process.exit(1)});
